const cache=new Map(),rateLimitMap=new Map(),inflight=new Map(),metrics={requests:0,errors:0};
const sh={'Strict-Transport-Security':'max-age=31536000; includeSubDomains; preload','X-Content-Type-Options':'nosniff','X-Frame-Options':'DENY','Referrer-Policy':'strict-origin-when-cross-origin','Access-Control-Allow-Origin':'*','Access-Control-Allow-Methods':'GET, POST, DELETE, OPTIONS','Access-Control-Allow-Headers':'Content-Type, Authorization'};
function json(d,s=200,e={}){return new Response(JSON.stringify(d),{status:s,headers:{'Content-Type':'application/json',...sh,...e}});}
function err(m,s=400){return json({error:m},s);}
function gc(k){const e=cache.get(k);return e?e.data:null;}
function sc(k,d,t){cache.set(k,{data:d,expiry:Date.now()+t});}
function crl(ip,l,w){const n=Date.now(),e=rateLimitMap.get(ip);if(!e||n>e.resetAt){rateLimitMap.set(ip,{count:1,resetAt:n+w});return true;}if(e.count>=l)return false;e.count++;return true;}
function san(s){return s.replace(/[<>]/g,'').replace(/javascript:/gi,'').replace(/on\w+\s*=/gi,'').replace(/\0/g,'').trim();}
async function fj(u,ep,i){const k=ep+':'+u;if(inflight.has(k))return inflight.get(k);const p=(async()=>{const r=await fetch(u,i);if(!r.ok)throw new Error('Upstream '+r.status);return r.json();})();inflight.set(k,p);try{return await p;}finally{inflight.delete(k);}}
async function hn(){const c=gc('hn');if(c)return c;const ids=await fj('https://hacker-news.firebaseio.com/v0/topstories.json','hn-top');const s=[];for(let i=0;i<Math.min(ids.length,30);i+=10){const b=ids.slice(i,i+10);const r=await Promise.allSettled(b.map(function(id){return fj('https://hacker-news.firebaseio.com/v0/item/'+id+'.json','hn-'+id);}));for(const x of r)if(x.status==='fulfilled'){const v=x.value;s.push({id:v.id,title:v.title,url:v.url,score:v.score,author:v.by,time:v.time,comments:v.descendants||0});}}sc('hn',s,300000);return s;}
async function gbp(req,env,ip){if(!crl(ip,5,600000))return err('Rate limit exceeded',429);let b;try{b=await req.json();}catch{return err('Invalid JSON');}if(b.website)return json({success:true});if(!b.name||!b.message)return err('name and message required');if(b.name.length>50||b.message.length>500)return err('Input too long');const e={id:crypto.randomUUID(),name:san(b.name),message:san(b.message),created:Date.now()};if(env.GUESTBOOK)await env.GUESTBOOK.put('entry:'+e.id,JSON.stringify(e));return json({success:true,entry:e},201);}
export default{async fetch(request,env,ctx){const url=new URL(request.url),path=url.pathname;if(request.method==='OPTIONS'&&path.startsWith('/api/'))return new Response(null,{status:204,headers:{'Access-Control-Allow-Origin':'*','Access-Control-Allow-Methods':'GET, POST, DELETE, OPTIONS','Access-Control-Allow-Headers':'Content-Type, Authorization','Access-Control-Max-Age':'86400'}});if(path.startsWith('/api/')){const ap=path.slice(5),st=Date.now();try{let r;if(ap==='health')r=json({status:'ok',timestamp:Date.now()});else if(ap==='crypto-ticker'){const c=gc('ct');if(c)r=json(c);else{const d=await fj('https://api.binance.com/api/v3/ticker/24hr','ct');sc('ct',d,10000);r=json(d);}}else if(ap==='fear-greed'){const c=gc('fg');if(c)r=json(c);else{const d=await fj('https://api.alternative.me/fng/','fg');sc('fg',d,300000);r=json(d);}}else if(ap==='hacker-news'){r=json(await hn());}else if(ap==='earthquakes'){const c=gc('eq');if(c)r=json(c);else{const d=await fj('https://earthquake.usgs.gov/earthquakes/feed/v1.0/summary/all_day.geojson','eq');sc('eq',d,300000);r=json(d);}}else if(ap==='kp-index'){const c=gc('kp');if(c)r=json(c);else{const d=await fj('https://services.swpc.noaa.gov/products/noaa-planetary-k-index.json','kp');sc('kp',d,600000);r=json(d);}}else if(ap==='mempool'){const c=gc('mp');if(c)r=json(c);else{const f=await fj('https://mempool.space/api/v1/fees/recommended','mpf');const s=await fj('https://mempool.space/api/mempool','mps');sc('mp',{fees:f,mempool:s},60000);r=json({fees:f,mempool:s});}}else if(ap==='coingecko-global'){const c=gc('cg');if(c)r=json(c);else{const d=await fj('https://api.coingecko.com/api/v3/global','cg');sc('cg',d,300000);r=json(d);}}else if(ap==='exchange-rates'){const c=gc('er');if(c)r=json(c);else{const d=await fj('https://api.exchangerate-api.com/v4/latest/USD','er');sc('er',d,3600000);r=json(d);}}else if(ap==='llm-benchmarks'){const c=gc('llm');if(c)r=json(c);else{const d=await fj('https://raw.githubusercontent.com/mlabonne/llm-leaderboard/main/data/llm_leaderboard.json','llm');sc('llm',d,21600000);r=json(d);}}else if(ap==='github-trending'){const c=gc('gh');if(c)r=json(c);else{const d=await fj('https://api.github.com/search/repositories?q=stars:>1000&sort=stars&order=desc&per_page=25','gh',{headers:{'User-Agent':'hydrated/1.0'}});sc('gh',d,1800000);r=json(d);}}else if(ap==='binance-klines'){const sym=url.searchParams.get('symbol')||'BTCUSDT',iv=url.searchParams.get('interval')||'1h',lm=url.searchParams.get('limit')||'100',ck='kl:'+sym+':'+iv+':'+lm;const c=gc(ck);if(c)r=json(c);else{const d=await fj('https://api.binance.com/api/v3/klines?symbol='+sym+'&interval='+iv+'&limit='+lm,'kl');sc(ck,d,300000);r=json(d);}}else if(ap==='stock-chart'){const sym=url.searchParams.get('symbol'),rng=url.searchParams.get('range')||'1d',iv=url.searchParams.get('interval')||'5m';if(!sym)r=json({error:'symbol required'},400);else{const ck='st:'+sym+':'+rng+':'+iv;const c=gc(ck);if(c)r=json(c);else{const d=await fj('https://query1.finance.yahoo.com/v8/finance/chart/'+encodeURIComponent(sym)+'?range='+rng+'&interval='+iv,'st');sc(ck,d,300000);r=json(d);}}}else if(ap==='weather'){const lat=url.searchParams.get('lat'),lon=url.searchParams.get('lon');if(!lat||!lon)r=json({error:'lat and lon required'},400);else{const ck='wx:'+lat+':'+lon;const c=gc(ck);if(c)r=json(c);else{const d=await fj('https://api.open-meteo.com/v1/forecast?latitude='+lat+'&longitude='+lon+'&current=temperature_2m,relative_humidity_2m,apparent_temperature,wind_speed_10m,weather_code&daily=temperature_2m_max,temperature_2m_min,weather_code&timezone=auto&forecast_days=7','wx');sc(ck,d,300000);r=json(d);}}}else if(ap==='social-sentiment'){const c=gc('ss');if(c)r=json(c);else{try{const d=await fj('https://www.reddit.com/r/cryptocurrency/hot.json?limit=25','ss',{headers:{'User-Agent':'hydrated/1.0'}});const posts=d&&d.data&&d.data.children||[];const pos=['bullish','moon','pump','gain','profit','surge','rally'];const neg=['bearish','dump','crash','loss','sell','decline','plunge'];let p=0,n=0;for(const x of posts){const t=((x.data.title||'')+' '+(x.data.selftext||'')).toLowerCase();for(const w of pos)if(t.includes(w))p++;for(const w of neg)if(t.includes(w))n++;}const total=p+n||1;const score=Math.round((p/total)*100);const result={score:score,label:score>60?'Bullish':score<40?'Bearish':'Neutral',positive:p,negative:n,sampleSize:posts.length};sc('ss',result,900000);r=json(result);}catch(e2){r=json({score:50,label:'Neutral',sampleSize:0});}}}else if(ap==='metrics'){r=json({requests:metrics.requests,errors:metrics.errors,cacheSize:cache.size});}else if(ap==='guestbook'||ap==='guestbook/'){if(request.method==='GET'){const entries=[{id:'1',name:'Visitor',message:'Great site!',created:Date.now()-86400000},{id:'2',name:'Dev',message:'Love the WASM widgets.',created:Date.now()-3600000}];r=json({entries:entries});}else if(request.method==='POST'){const ip=request.headers.get('CF-Connecting-IP')||'unknown';r=await gbp(request,env,ip);}else r=json({error:'Method not allowed'},405);}else r=json({error:'Not found'},404);const dur=Date.now()-st;r.headers.set('X-Response-Time',dur+'ms');r.headers.set('X-API-Version','v1');metrics.requests++;return r;}catch(e3){metrics.errors++;return json({error:'Internal server error'},500);}}return env.ASSETS.fetch(request);}};
